messages.content:
{
  "required_details": [
    {
      "field": "Invoice number",
      "description": "Unique identifier for the invoice (used for tracking and payment).",
      "example": "INV-2026-0457"
    },
    {
      "field": "Invoice date",
      "description": "Date the invoice was issued.",
      "example": "2026-03-08"
    },
    {
      "field": "Amount due (total)",
      "description": "Total payable amount and currency.",
      "example": "USD 4,250.00"
    },
    {
      "field": "Payment due date / terms",
      "description": "When payment is due and any terms (e.g., Net30).",
      "example": "Due: 2026-04-07 (Net30)"
    },
    {
      "field": "Customer / recipient name",
      "description": "Name of the company or individual receiving the invoice and a contact person if available.",
      "example": "Global Shipper (Attn: Maria Lopez)"
    },
    {
      "field": "Billing address",
      "description": "Official billing address to appear on the invoice.",
      "example": "Global Shipper, 123 Harbor Drive, Suite 400, Long Beach, CA 90802"
    },
    {
      "field": "Invoice line items / description",
      "description": "Breakdown of charges (service descriptions, quantities, unit price, line total).",
      "example": "Ocean freight (FCL) — 1 x 20ft container — USD 3,800.00; Documentation fee — USD 100.00"
    },
    {
      "field": "Tax / VAT (if applicable)",
      "description": "Tax amount and rate, or note if tax-exempt.",
      "example": "Sales tax 8.25% — USD 350.00"
    },
    {
      "field": "Currency",
      "description": "Currency used for the invoice and payment.",
      "example": "USD"
    },
    {
      "field": "Purchase order or reference number (if provided)",
      "description": "Customer PO or internal reference to tie the invoice to a contract or order.",
      "example": "PO: GS-78921"
    },
    {
      "field": "Shipment reference / BOL / booking number",
      "description": "Shipment identifiers so the customer knows which movement the invoice covers.",
      "example": "BOL: NPT-2026-3345 / Booking: GS-3345"
    }
  ],
  "optional_but_recommended": [
    "Remittance instructions (bank name, account number, SWIFT/BIC, routing/ABA, account name).",
    "Accepted payment methods (ACH, wire, card) and any processing fees or special instructions.",
    "Company tax ID or VAT registration number (for customer and NexPort if required).",
    "Late payment terms and any interest/penalty details.",
    "Contact person for billing questions (name, email, phone).",
    "Invoice terms or short note (e.g., 'Thank you for your business')."
  ],
  "attachments": [
    "Invoice PDF (filename should include invoice number, e.g., INV-2026-0457.pdf)",
    "Supporting documents as needed: packing list, BOL, proof of delivery (POD), rate confirmation"
  ],
  "email_subject_template": "Requested Invoice INV-2026-0457 — Global Shipper",
  "email_body_template": "Hello Maria,\n\nAttached is the invoice you requested for Global Shipper: Invoice INV-2026-0457, dated 2026-03-08, for USD 4,250.00. Payment terms: Due 2026-04-07 (Net30).\n\nAccepted payment methods: Wire transfer (Bank: First Bank; Account: 123456789; SWIFT: FBUSUS33). If you need a different payment method or the invoice in another format, please let me know. If you require supporting documents (packing list, BOL, POD), I can attach them as well.\n\nBest regards,\nKatya\nNexPort Logistics\naccounts@nexport.com",
  "next_steps": "Fill in the required fields above, attach the invoice PDF (and any supporting docs), and if you want me to send the email from accounts@nexport.com, reply with the recipient email address and confirm the attachment file names. I can then send it on your behalf."
}

