  "message": "I can send the invoice from accounts@nexport.com or provide the final email text for you to paste, but I need three confirmations before proceeding. Please reply with the exact items below.",
  "required_inputs": [
    {
      "name": "recipient_email",
      "instruction": "Provide the exact recipient email address to send the invoice to (e.g., maria.lopez@globalshipper.com). I will not guess or invent addresses."
    },
    {
      "name": "attachment_handling",
      "instruction": "Choose one option id and include any required data:",
      "options": {
        "attach_later": "I will send the email body now from accounts@nexport.com; you must attach INV-2026-0457.pdf from your email client afterwards (the send tool cannot attach local files).",
        "include_link": "You provide a secure, shareable URL to INV-2026-0457.pdf and I will include that link in the email body. If chosen, supply the URL.",
        "you_send": "You will send the email with the attachment yourself; I will return the final email text for you to paste and send."
      }
    },
    {
      "name": "remittance_instructions",
      "instruction": "Either provide remittance/bank details to include OR reply 'Omit remittance instructions'. Only include these if you are authorized to share them.",
      "template_fields": [
        "Bank name",
        "Account name",
        "Account number or IBAN",
        "SWIFT / BIC",
        "Routing / ABA (if US)",
        "Payment reference (e.g., INV-2026-0457)"
      ]
    }
  ],
  "constraints": [
    "I will not invent or assume recipient email addresses—please supply the exact address.",
    "The send tool cannot attach local files. To deliver the PDF, either provide a secure URL (include_link) or choose attach_later and attach the file from your client after I send the body."
  ],
  "email_preview": {
    "subject": "Requested Invoice INV-2026-0457 — Global Shipper",
    "body": "Hello Maria,\n\nAttached is the invoice you requested for Global Shipper: Invoice INV-2026-0457, dated 2026-03-08, for USD 4,250.00. Payment terms: Due 2026-04-07 (Net30).\n\nInvoice details:\n- Ocean freight (FCL) — 1 x 20ft container — USD 3,800.00\n- Documentation fee — USD 100.00\n- Tax: Sales tax 8.25% — USD 350.00\n- Shipment reference: BOL: NPT-2026-3345 / Booking: GS-3345\n\nIf you provided a download link I will include it; if you want remittance instructions added, I will append them as supplied.\n\nBest regards,\nKatya\nNexPort Logistics\naccounts@nexport.com"
  },
  "next_steps": "Reply with (1) recipient_email, (2) chosen attachment_handling option id (and URL if include_link), and (3) remittance_instructions or 'Omit remittance instructions'. After that, reply 'Send now' if you want me to send the email from accounts@nexport.com (note: I cannot attach local files)."
}

